constexpr const FinalMuSkin* FindFinalMuSkin(int type)
{
    size_t first = 0, last = FinalMuSkins.size();
    while (first < last)
    {
        const size_t middle = first + (last - first) / 2;
        if (FinalMuSkins[middle].type < type) first = middle + 1;
        else last = middle;
    }
    return first < FinalMuSkins.size() && FinalMuSkins[first].type == type ? &FinalMuSkins[first] : nullptr;
}
